css:
@keyframes bounce {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-8px);
  }
}

.main-container {
  width: 300px;
  height: 250px;
  background-color: #3b3d38;
  position: relative;
  box-shadow: inset 0 0 4px 4px #282927;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: bounce 2s steps(8) infinite;
}

.text {
  color: lightgray;
  font-weight: 900;
}

.main-container::before {
  content: "";
  position: absolute;
  inset: -12px;
  z-index: -1;

  background: linear-gradient(
      to right,
      #a1a896 0 4px,
      #7b7f70 4px 8px,
      #575a53 8px 12px,
      transparent 12px
    ),
    linear-gradient(
      to left,
      #575a53 0 4px,
      #7b7f70 4px 8px,
      #a1a896 8px 12px,
      transparent 12px
    ),
    linear-gradient(
      to bottom,
      #a1a896 0 4px,
      #7b7f70 4px 8px,
      #575a53 8px 12px,
      transparent 12px
    ),
    linear-gradient(
      to top,
      #575a53 0 4px,
      #7b7f70 4px 8px,
      #a1a896 8px 12px,
      transparent 12px
    );
}

.top-left {
  top: -16px;
  left: -16px;
}

.top-right {
  top: -16px;
  right: -16px;
}

.bottom-left {
  bottom: -16px;
  left: -16px;
}

.bottom-right {
  bottom: -16px;
  right: -16px;
}

.corner-container {
  position: absolute;
}

.corner {
  width: 20px;
  aspect-ratio: 1/1;
  background-color: #7b7f70;
}

.first-corner {
  width: 80%;
  height: 80%;
  position: absolute;
  top: 0;
  left: 0;
  background-color: #a1a896;
  z-index: 1;
}

.second-corner {
  width: 80%;
  height: 80%;
  position: absolute;
  bottom: 0;
  right: 0;
  background-color: #575a53;
  z-index: 1;
}

.center-corner {
  width: 60%;
  height: 60%;
  position: absolute;
  top: 20%;
  left: 20%;
  background-color: #575a53;
  z-index: 1;
}

.inner-center-corner {
  width: 40%;
  height: 40%;
  position: absolute;
  top: 40%;
  left: 40%;
  background-color: #a1a896;
  z-index: 1;
}

.inner-center {
  width: 20%;
  height: 20%;
  position: absolute;
  top: 40%;
  left: 40%;
  background-color: #7b7f70;
  z-index: 1;
}

.inner-center-bottom-left {
  width: 20%;
  height: 20%;
  position: absolute;
  top: 60%;
  left: 20%;
  background-color: #7b7f70;
  z-index: 1;
}

.inner-center-top-right {
  width: 20%;
  height: 20%;
  position: absolute;
  top: 20%;
  left: 60%;
  background-color: #7b7f70;
  z-index: 1;
}
